-- =============================================================================
-- 569 — LE CAHIER D'EXERCICES DE 6E
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/6e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 569 --niveau 6e --fichiers sport.culture > supabase/contenu/569_exercices_6e.sql
--
-- 30 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (0/0/5 gemmes depuis la 557, 20/35/50 XP), réglables ensuite en base.
--
--   sport.culture           30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Le but refusé de Malik","competence":"observer-schema","situation":"Samedi, Malik pense avoir marqué, mais l’arbitre refuse le but pour hors-jeu. Sur le schéma, on voit la scène au moment précis où Léo lui envoie la passe. L’équipe violette attaque vers la droite.","documents":[{"id":"terrain","type":"schema","titre":"La passe de Léo, vue de dessus","source":"Schéma écrit pour l’exercice.","largeur":340,"hauteur":230,"elements":[{"forme":"rect","x":20,"y":30,"l":300,"h":170,"teinte":"vert","motif":"clair"},{"forme":"texte","x":170,"y":18,"texte":"Sens de l’attaque →","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":320,"y":218,"texte":"Ligne de but","taille":"petit","ancre":"fin"},{"forme":"cercle","cx":298,"cy":115,"r":12,"teinte":"jaune","motif":"plein","texte":"G","id":"z1","zone":true},{"forme":"cercle","cx":240,"cy":75,"r":12,"teinte":"corail","motif":"plein","texte":"B","id":"z2","zone":true},{"forme":"cercle","cx":185,"cy":155,"r":12,"teinte":"corail","motif":"plein","texte":"C","id":"z3","zone":true},{"forme":"cercle","cx":268,"cy":160,"r":12,"teinte":"violet","motif":"plein","texte":"M","id":"z4","zone":true},{"forme":"cercle","cx":100,"cy":105,"r":12,"teinte":"violet","motif":"plein","texte":"L","id":"z5","zone":true},{"forme":"emoji","x":128,"y":112,"emoji":"⚽","taille":18},{"forme":"ligne","de":[118,112],"a":[254,156],"fleche":"fin","style":"pointilles","teinte":"violet"},{"forme":"texte","x":24,"y":218,"texte":"G gardien · B, C défenseurs","taille":"petit","ancre":"debut"}]}],"questions":[{"enonce":"Touche l’**avant-dernier défenseur** de l’équipe qui défend (le gardien est le dernier).","aide":"Pars de la ligne de but : le gardien est le premier joueur rencontré, l’avant-dernier défenseur est le suivant.","type":"zone","document":"terrain","multiple":false},{"enonce":"Au moment où Léo passe, Malik est-il en **position de hors-jeu** ?","aide":"Compare la place de Malik avec celle du ballon, puis avec celle du défenseur B, en regardant vers la ligne de but.","type":"choix","options":[{"id":"a","texte":"Non : le gardien ne compte pas comme défenseur"},{"id":"b","texte":"Oui : mais seulement parce qu’il porte un maillot violet"},{"id":"c","texte":"Non : il est trop loin du ballon"},{"id":"d","texte":"Oui : il est plus près de la ligne de but que le ballon et que l’avant-dernier défenseur"}],"multiple":false},{"enonce":"Combien d’adversaires (gardien compris) se trouvent entre Malik et la ligne de but ?","aide":"Compte les joueurs rouges et jaunes qui sont plus près de la ligne de but que Malik.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le gardien est le dernier défenseur, donc l’avant-dernier est le joueur **B**. C’est lui qui fixe la ligne du hors-jeu."},{"cle":{"type":"choix","ids":["d"]},"explication":"Malik est devant le ballon **et** devant B : il est en **position de hors-jeu**. Comme il reçoit ensuite la balle et marque, il participe au jeu : le but est refusé."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"Seul le **gardien** est plus près du but que Malik. Il en faudrait au moins deux pour que Malik ne soit pas en position de hors-jeu."}]$ex$::jsonb),
  ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Le compte rendu du match","competence":"analyser-document","situation":"Après le match U12 entre Sablons et Bellevue, l’entraîneur colle le compte rendu dans le vestiaire. Retrouve ce qui s’est passé grâce à la règle du jeu.","documents":[{"id":"compte-rendu","type":"fiche","modele":"affiche","entete":"Sablons 2 – 1 Bellevue","sousTitre":"Compte rendu du match U12","emoji":"⚽","lignes":[{"texte":"But de Lina refusé : hors-jeu","valeur":"12’","id":"z1"},{"texte":"But de Tom sur corner : accordé","valeur":"27’","id":"z2"},{"texte":"Carton jaune pour Yanis (Bellevue)","valeur":"41’","id":"z3"},{"texte":"Penalty pour Sablons, faute dans la surface","valeur":"55’","id":"z4"},{"texte":"Second carton jaune pour Yanis","valeur":"68’","id":"z5"},{"texte":"But de Nour : accordé","valeur":"80’","id":"z6"}],"pied":"Chaque équipe avait 11 joueurs au coup d’envoi.","teinte":"vert"}],"questions":[{"enonce":"Touche la ligne qui explique pourquoi **Bellevue finit le match à dix**.","aide":"Que se passe-t-il quand un joueur reçoit deux cartons jaunes dans le même match ?","type":"zone","document":"compte-rendu","multiple":false},{"enonce":"À quelle distance du but se tire le penalty de la 55e minute ?","aide":"Le penalty se tire face au seul gardien, depuis un point marqué dans la surface de réparation.","type":"choix","options":[{"id":"a","texte":"À 11 mètres"},{"id":"b","texte":"À 16 mètres"},{"id":"c","texte":"À 6 mètres"},{"id":"d","texte":"Depuis le point central"}],"multiple":false},{"enonce":"Le but de Tom (27’) est marqué sur un corner. Pourquoi ne peut-il pas être refusé pour hors-jeu ?","aide":"Relis la liste des situations où le hors-jeu n’existe pas : touche, corner, coup de pied de but…","type":"choix","options":[{"id":"a","texte":"Parce que Tom jouait dans sa moitié de terrain"},{"id":"b","texte":"Parce qu’il n’y a jamais de hors-jeu sur un corner"},{"id":"c","texte":"Parce que l’arbitre a oublié de siffler"},{"id":"d","texte":"Parce que le gardien a touché le ballon"}],"multiple":false},{"enonce":"Combien de joueurs Bellevue compte-t-il sur le terrain à la fin du match ?","aide":"Ils étaient 11 au départ. Combien d’expulsions, et un joueur expulsé est-il remplacé ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"À la 68e minute, Yanis reçoit un **second carton jaune** : il est expulsé, comme avec un carton rouge. Son équipe finit à dix, sans pouvoir le remplacer."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le penalty se tire à **11 mètres** du but, face au seul gardien."},{"cle":{"type":"choix","ids":["b"]},"explication":"Sur un **corner**, comme sur une touche ou un coup de pied de but, **il n’y a pas de hors-jeu**. Le but de Tom est donc valable."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"Bellevue commence à 11 et perd Yanis, qui n’est pas remplaçable : **10 joueurs** à la fin."}]$ex$::jsonb),
  ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Hors-jeu : la dispute de la récré","competence":"raisonner","situation":"Inès et Noah débattent d’un but refusé pendant un match de la récré. Noah a les règles en tête, Inès un peu moins. Le tableau résume cinq actions de la semaine : à vous de les juger.","documents":[{"id":"dispute","type":"dialogue","modele":"sms","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Noah","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Ton but était refusé, c’est logique : tu étais devant le dernier défenseur, donc c’est toujours une faute."},{"qui":"Noah","texte":"Non ! Être devant, c’est juste une position. C’est puni seulement si je joue le ballon ou si je gêne quelqu’un."},{"qui":"Inès","texte":"Et sur un corner alors ?"},{"qui":"Noah","texte":"Là, jamais de hors-jeu. Regarde le tableau."}]},{"id":"actions","type":"tableau","titre":"Cinq actions de la semaine","source":"Situations imaginées pour l’exercice.","colonnes":["Action","Position de l’attaquant","Origine du ballon","Ce qu’il fait"],"lignes":[["A","Devant l’avant-dernier défenseur","Passe d’un coéquipier","Prend le ballon et marque"],["B","Devant l’avant-dernier défenseur","Corner","Marque de la tête"],["C","Dans sa propre moitié de terrain","Longue passe","Contrôle et file au but"],["D","Devant l’avant-dernier défenseur","Passe d’un coéquipier","Reste loin de l’action, ne gêne personne"],["E","À la hauteur de l’avant-dernier défenseur","Passe d’un coéquipier","Prend le ballon et marque"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les mots de l’**erreur** d’Inès dans la conversation.","aide":"Selon Noah, que faut-il en plus d’être devant le dernier défenseur pour être sanctionné ?","type":"zone","document":"dispute","multiple":true},{"enonce":"Pour chacune des cinq actions, dis si le hors-jeu est **sanctionné** ou non.","aide":"Pour être sanctionné, il faut être en position de hors-jeu ET participer au jeu, et l’action ne doit pas être dans une situation « sans hors-jeu ».","type":"categories","categories":[{"id":"c0","texte":"But refusé : hors-jeu"},{"id":"c1","texte":"Pas de sanction"}],"items":[{"id":"i0","texte":"Action A"},{"id":"i1","texte":"Action C"},{"id":"i2","texte":"Action B"},{"id":"i3","texte":"Action E"},{"id":"i4","texte":"Action D"}]},{"enonce":"Touche la case qui explique pourquoi l’action B ne peut **jamais** être un hors-jeu.","aide":"Cherche, dans la ligne B, la colonne qui dit d’où vient le ballon.","type":"zone","document":"actions","multiple":false},{"enonce":"Complète la règle de base du hors-jeu.","aide":"Relis la scène : on compare la place de l’attaquant avec celle du ballon, puis avec celle d’un défenseur qui n’est pas le gardien.","type":"trous","segments":["On est en position de hors-jeu quand on est plus près de la ligne de but que le ",0," et que l’",1," défenseur."],"banque":["gardien","avant-dernier","dernier","ballon","arbitre"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m15","m16","m17","m18"]},"explication":"Être en position de hors-jeu **n’est pas une faute en soi**. Il faut en plus participer au jeu : toucher le ballon, gêner un adversaire ou profiter de la situation."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c1"}},"explication":"Seule l’action **A** est sanctionnée. B : corner. C : propre moitié de terrain. D : en position mais sans participer. E : à la hauteur du défenseur, donc pas devant."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Le ballon vient d’un **corner** : sur un corner, il n’y a pas de hors-jeu, quelle que soit la position de l’attaquant."},{"cle":{"type":"trous","trous":[["ballon"],["avant dernier"]]},"affichage":"ballon · avant-dernier","explication":"On est en position de hors-jeu devant le **ballon** et devant l’**avant-dernier** défenseur (le gardien compte comme dernier)."}]$ex$::jsonb),
  ('db2a6a93-e520-568c-8e31-b44eed648b59'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Le bilan de Camille","competence":"lire-tableau","situation":"Camille joue au basket au collège. Après le match de samedi, son entraîneur note ce qu’elle a réussi. À toi de lire ses statistiques.","documents":[{"id":"stats","type":"tableau","titre":"Les tirs réussis par Camille","source":"Chiffres imaginés pour l’exercice.","colonnes":["Type de tir","Points par tir","Tirs réussis"],"lignes":[["Lancer franc",1,4],["Tir à l’intérieur de la ligne",2,3],["Tir derrière la ligne à trois points",3,2]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui dit combien **rapporte** un tir réussi derrière la ligne.","aide":"Va à la ligne « Tir derrière la ligne à trois points », puis à la colonne « Points par tir ».","type":"zone","document":"stats","multiple":false},{"enonce":"Combien de points Camille a-t-elle marqués en tout ?","aide":"Multiplie, ligne par ligne, les points par tir et le nombre de tirs réussis, puis additionne.","type":"nombre"},{"enonce":"Pourquoi un tir derrière la ligne rapporte-t-il **3 points** plutôt que 2 ?","aide":"La ligne est à 6,75 m du panier en règles internationales. Que récompense-t-on ?","type":"choix","options":[{"id":"a","texte":"Parce que le ballon est plus lourd"},{"id":"b","texte":"Parce que le panier est plus haut de ce côté"},{"id":"c","texte":"Parce qu’il est tiré de plus loin du panier, donc plus difficile"},{"id":"d","texte":"Parce qu’il est tiré sans défenseur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Un tir réussi derrière la ligne vaut **3 points**."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"4 × 1 + 3 × 2 + 2 × 3 = 4 + 6 + 6 = **16 points**."},{"cle":{"type":"choix","ids":["c"]},"explication":"La ligne est à **6,75 m** du panier (7,24 m en NBA) : plus le tir est loin, plus il est difficile, donc mieux récompensé."}]$ex$::jsonb),
  ('db2a6a93-e520-568c-8e31-b44eed648b59'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Les chronos du maître de jeu","competence":"se-reperer-temps","situation":"Les Rouges et les Bleus s’affrontent. Pour chaque attaque, le chronométreur note à quel moment l’équipe récupère le ballon, franchit la ligne médiane et tire. Une des deux équipes a enfreint une règle de temps.","documents":[{"id":"chronos","type":"tableau","titre":"Le chronomètre des attaques (en secondes)","source":"Relevés imaginés pour l’exercice.","colonnes":["Équipe","Récupère le ballon","Passe la ligne médiane","Tire"],"lignes":[["Rouges",0,6,20],["Bleus",0,9,22]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui montre qu’une équipe a **enfreint** une règle de temps.","aide":"Une équipe a droit à 8 secondes pour franchir la ligne médiane. Qui a pris plus de temps ?","type":"zone","document":"chronos","multiple":false},{"enonce":"Quand les Rouges franchissent la ligne médiane, combien de secondes **restent-elles** sur les 24 secondes pour tirer ?","aide":"Les 24 secondes démarrent quand l’équipe récupère le ballon.","type":"nombre","unite":"s"},{"enonce":"Les Rouges tirent à 20 s. De combien de secondes **restait-il** avant la fin des 24 secondes ?","aide":"Calcule la différence entre 24 et le moment du tir.","type":"nombre","unite":"s"},{"enonce":"Que se passe-t-il pour les Bleus ?","aide":"Dépasser un délai donne le ballon à l’adversaire, sans qu’il y ait eu de faute de contact.","type":"choix","options":[{"id":"a","texte":"Rien : les 8 secondes ne comptent qu’en NBA"},{"id":"b","texte":"Ils perdent le ballon, remis à l’adversaire"},{"id":"c","texte":"L’arbitre arrête le match"},{"id":"d","texte":"Ils gagnent un lancer franc"}],"multiple":false}]}$ex$::jsonb,
