  ('caf2e6dc-508d-55a9-9839-889dc574b8da'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"La gourde oubliée de Nadia","competence":"comprendre-langue","situation":"Nadia a joué un tournoi de handball sous un gymnase très chaud, sans sa gourde. Elle raconte sa journée à son entraîneur par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Nadia","emoji":"👧","cote":"gauche"},{"nom":"Coach","emoji":"🧑‍🏫","cote":"droite"}],"repliques":[{"qui":"Nadia","texte":"J’ai joué 2 heures sans boire. Je transpirais énormément, environ 1,5 litre par heure !"},{"qui":"Nadia","texte":"Mais je ne comprends pas : plus ça coule, plus je devrais être au frais, non ?"},{"qui":"Coach","texte":"Pas du tout. Ce qui refroidit, c’est la sueur qui s’évapore, pas celle qui coule."},{"qui":"Nadia","texte":"Et dans un gymnase fermé, avec l’air humide ?"},{"qui":"Coach","texte":"L’évaporation est lente : la sueur coule « pour rien ». Bois avant d’avoir soif !"}]}],"questions":[{"enonce":"Touche le mot qui montre l’**idée fausse** de Nadia sur la sueur.","aide":"Nadia croit que la sueur refroidit en tombant de la peau. Quel mot le montre ?","type":"zone","document":"sms","multiple":false},{"enonce":"Combien de litres d’eau Nadia a-t-elle perdus pendant son tournoi ?","aide":"Multiplie la quantité perdue par heure par le nombre d’heures jouées.","type":"nombre","unite":"L"},{"enonce":"Relie chaque situation à la vitesse d’évaporation de la sueur.","aide":"Pense à ce que fait l’air : il emporte l’eau de la peau, ou non.","type":"association","gauche":[{"id":"g0","texte":"Air sec et ventilé"},{"id":"g1","texte":"Air humide, sans vent"},{"id":"g2","texte":"Vêtement imperméable"}],"droite":[{"id":"d0","texte":"Évaporation bloquée"},{"id":"d1","texte":"Évaporation lente"},{"id":"d2","texte":"Évaporation rapide"}]},{"enonce":"Quel conseil le coach donne-t-il à Nadia pour le prochain tournoi ?","aide":"Relis la dernière réplique du coach.","type":"choix","options":[{"id":"a","texte":"Boire avant d’avoir soif"},{"id":"b","texte":"Boire seulement quand la soif apparaît"},{"id":"c","texte":"Remplacer l’eau par du coton"},{"id":"d","texte":"Ne pas boire pour ne pas avoir mal au ventre"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"Nadia croit que la sueur qui **coule** refroidit. En réalité, seule celle qui **s’évapore** enlève de la chaleur."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 L","explication":"1,5 L × 2 h = **3 litres** : sans boire, la déshydratation guette."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Air sec et ventilé : on se refroidit bien. Air humide : la sueur coule pour rien. Imperméable : la chaleur reste piégée."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quand la soif apparaît, le manque d’eau a déjà commencé : on boit **avant d’avoir soif**, par petites gorgées."}]$ex$::jsonb),
