  ('fa6391f9-219d-512b-9b29-bda6efed26c9'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"La séance de Mélissa","competence":"lire-graphique","situation":"Mélissa, 12 ans, porte une montre qui mesure sa fréquence cardiaque pendant sa séance d’entraînement de trente minutes.","documents":[{"id":"fc","type":"graphique","forme":"courbe","titre":"La fréquence cardiaque de Mélissa","source":"Mesures imaginées pour l’exercice.","categories":["0","5","10","15","20","25","30"],"series":[{"nom":"Battements par minute","valeurs":[78,120,160,185,150,110,90],"teinte":"corail"}],"axeY":{"titre":"Fréquence cardiaque","unite":"battements/min","min":40,"max":220,"pas":20},"axeX":{"titre":"Minutes depuis le début"},"valeurs":false}],"questions":[{"enonce":"Touche le moment où le cœur de Mélissa bat **le plus vite**.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"fc","multiple":false},{"enonce":"Quelle est la fréquence cardiaque maximale **estimée** de Mélissa avec la formule 220 − âge ?","aide":"Mélissa a 12 ans.","type":"nombre","unite":"battements/min"},{"enonce":"Quelle marge lui restait-il entre son pic mesuré et cette estimation ?","aide":"Soustrais son pic (185) à 208.","type":"nombre","unite":"battements/min"},{"enonce":"À 30 minutes, son cœur bat à 90. Qu’est-ce que cela montre ?","aide":"Compare avec la valeur de départ (78) et avec le pic.","type":"choix","options":[{"id":"a","texte":"Que la montre est en panne"},{"id":"b","texte":"Qu’elle est en danger"},{"id":"c","texte":"Qu’il s’est arrêté"},{"id":"d","texte":"Qu’il se calme progressivement après l’effort"}],"multiple":false}]}$ex$::jsonb,
