   $ex${"titre":"Le cœur d’athlète et le point de côté","competence":"argumenter","situation":"Camille a eu un point de côté en courant juste après son goûter. Son professeur lui montre un graphique sur le cœur des sportifs et discute avec elle.","documents":[{"id":"repos","type":"graphique","forme":"barres","titre":"Le pouls au repos de quatre personnes","source":"Valeurs imaginées pour l’exercice, d’après les ordres de grandeur du cours.","categories":["Élève sédentaire","Élève sportive","Coureur amateur","Champion d’endurance"],"series":[{"nom":"Pouls au repos","valeurs":[75,65,55,40],"teinte":"violet"}],"axeY":{"titre":"Battements par minute","min":0,"max":80,"pas":10},"valeurs":false},{"id":"dialogue","type":"dialogue","modele":"sms","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Prof","emoji":"🧑‍🏫","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"J’ai eu un point de côté dès les premiers tours, juste après avoir mangé."},{"qui":"Prof","texte":"Pas de panique. Ralentis, respire profondément en soufflant longtemps, et presse l’endroit douloureux."},{"qui":"Camille","texte":"Mon cœur envoie 5 litres de sang par minute au repos, mais là j’avais l’impression d’avoir plus."},{"qui":"Prof","texte":"À l’effort, il peut en envoyer 20 à 25 litres par minute."}]}],"questions":[{"enonce":"Touche la personne dont le cœur bat **le plus lentement** au repos.","aide":"Cherche la barre la plus basse.","type":"zone","document":"repos","multiple":false},{"enonce":"Quelle différence de pouls au repos y a-t-il entre l’élève sédentaire et le champion ?","aide":"Soustrais la plus petite valeur à la plus grande.","type":"nombre","unite":"battements/min"},{"enonce":"Au repos, combien de litres de sang le cœur de Camille envoie-t-il en **10 minutes** ?","aide":"Le dialogue donne le débit par minute.","type":"nombre","unite":"L"},{"enonce":"Remets dans l’ordre les gestes conseillés par le professeur.","aide":"On commence par réduire l’effort.","type":"ordre","items":[{"id":"a","texte":"Respirer profondément en soufflant longtemps"},{"id":"b","texte":"Presser avec la main à l’endroit de la douleur"},{"id":"c","texte":"Ralentir, voire marcher"}]},{"enonce":"Range chaque habitude : aide-t-elle à éviter le point de côté ou l’aggrave-t-elle ?","aide":"Le point de côté est favorisé par une digestion en cours et un effort brutal.","type":"categories","categories":[{"id":"c0","texte":"Aide à l’éviter"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Courir juste après avoir mangé"},{"id":"i1","texte":"Partir en sprint à froid"},{"id":"i2","texte":"Ne pas manger juste avant"},{"id":"i3","texte":"S’échauffer doucement"}]}]}$ex$::jsonb,
