   $ex${"titre":"Les bobos de Basile","competence":"analyser-texte","situation":"Basile a enchaîné trois jours sportifs. Il raconte ce qu’il a ressenti : à toi d’identifier chaque bobo.","documents":[{"id":"journal","type":"texte","genre":"recit","titre":"Le journal de Basile","auteur":"Récit écrit pour l’exercice","blocs":["Mardi, en plein entraînement, le mollet de Basile se contracte brutalement sans qu’il le décide.","Mercredi matin, ses cuisses sont raides : descendre l’escalier est une épreuve.","Jeudi, le frottement de sa chaussure a laissé une cloque sur son talon."]}],"questions":[{"enonce":"Touche le mot qui montre que la **crampe** est soudaine et involontaire.","aide":"Cherche le mot qui dit comment le muscle se contracte.","type":"zone","document":"journal","multiple":false},{"enonce":"Relie chaque bobo à son origine.","aide":"Relis les trois paragraphes du récit.","type":"association","gauche":[{"id":"g0","texte":"Crampe"},{"id":"g1","texte":"Courbature"},{"id":"g2","texte":"Ampoule"}],"droite":[{"id":"d0","texte":"Micro-lésions dans les fibres du muscle"},{"id":"d1","texte":"Frottement répété sur la peau"},{"id":"d2","texte":"Fatigue du muscle, parfois manque d’eau"}]},{"enonce":"Que doit faire Basile avec son ampoule ?","aide":"La peau protège la plaie des microbes.","type":"choix","options":[{"id":"a","texte":"Courir pour la faire éclater"},{"id":"b","texte":"La frotter pour qu’elle disparaisse"},{"id":"c","texte":"La percer tout de suite avec les doigts"},{"id":"d","texte":"Ne pas la percer et la protéger avec un pansement"}],"multiple":false}]}$ex$::jsonb,
