roid après l’effort.","type":"zone","document":"sac","multiple":true},{"enonce":"Que peut faire Mélodie au jour 2 pour atténuer ses courbatures ?","aide":"Bouger doucement aide, mais pas en forçant.","type":"choix","options":[{"id":"a","texte":"Marcher ou pédaler doucement"},{"id":"b","texte":"Refaire la même randonnée en courant"},{"id":"c","texte":"Prendre un bain de glace directement sur la jambe"},{"id":"d","texte":"Rester allongée pendant trois jours"}],"multiple":false}]}$ex$::jsonb,
