INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 6e : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;


-- =============================================================================
-- 569 — LE CATALOGUE DES CONTRÔLES BLANCS : 6e (sport)
--
-- 30 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 569 --niveau 6e --matieres sport
--
--   sport.culture                30 sujets · 10 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9'::uuid, 1, 'redaction', $exo${"titre":"Les règles du football","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Combien y a-t-il de joueurs par équipe sur le terrain, et combien de temps dure un match ?\n2. Explique ce qu’est une **position de hors-jeu**.\n3. Que se passe-t-il quand un joueur reçoit **deux cartons jaunes** dans le même match ?","bareme":[{"critere":"11 joueurs (gardien compris) et deux mi-temps de 45 minutes","points":5},{"critere":"Position de hors-jeu : plus près du but adverse que le ballon et que l’avant-dernier défenseur","points":8},{"critere":"Deux jaunes = un carton rouge : le joueur est expulsé et n’est pas remplacé","points":7}],"dureeMin":7,"corrige":"1. Une équipe compte **11 joueurs**, gardien compris. Un match dure **deux mi-temps de 45 minutes**.\n\n2. Un joueur est en **position de hors-jeu** quand, au moment où un coéquipier lui passe le ballon, il est **plus près de la ligne de but adverse que le ballon et que l’avant-dernier défenseur** (le gardien compte comme défenseur).\n\n3. **Deux cartons jaunes** donnent un **carton rouge** : le joueur est **expulsé** et son équipe finit le match à dix, car un carton rouge ne se remplace pas."}$exo$::jsonb),
  ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9'::uuid, 2, 'redaction', $exo${"titre":"Le but refusé","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Samedi, pendant un match, Inès joue attaquante. Voici trois actions.\n\n*Action A : Inès attend dans sa propre moitié de terrain, un coéquipier lui passe le ballon, elle est la joueuse la plus avancée de son équipe.*\n*Action B : Inès est devant l’avant-dernier défenseur au moment où une longue passe part. Elle prend le ballon et marque.*\n*Action C : Inès est devant la défense, mais le ballon arrive d’un corner.*\n\n1. Pour chaque action, dis si le but peut être annulé pour hors-jeu et explique pourquoi.\n2. Quelle différence fais-tu entre « être en position de hors-jeu » et « être sanctionné » ?\n3. Sur l’action B, une assistance vidéo aide l’arbitre à vérifier. Comment s’appelle cette aide et à quelle Coupe du monde est-elle apparue ?","bareme":[{"critere":"Action A et action C : pas de hors-jeu (sa moitié de terrain ; corner)","points":6},{"critere":"Action B : but annulé, Inès est en position de hors-jeu et participe au jeu en marquant","points":6},{"critere":"Différence : la position seule n’est pas une faute ; on est sanctionné si on participe au jeu","points":5},{"critere":"VAR, assistance vidéo, apparue en 2018","points":3}],"dureeMin":11,"corrige":"1. **Action A** : pas de hors-jeu, car on ne peut **jamais** être hors-jeu dans **sa propre moitié de terrain**. **Action C** : pas de hors-jeu non plus, car on ne peut pas l’être **sur un corner**. **Action B** : le but est **annulé**. Inès est **plus près du but que le ballon et que l’avant-dernier défenseur** au moment de la passe, donc en position de hors-jeu, et elle **participe au jeu** en prenant le ballon.\n\n2. Être en **position de hors-jeu** n’est **pas une faute** en soi. Le hors-jeu n’est **sanctionné** que si le joueur **participe au jeu** : il touche le ballon, gêne un adversaire ou profite de la situation.\n\n3. C’est la **VAR**, l’**assistance vidéo à l’arbitrage**, utilisée pour la première fois à une Coupe du monde en **2018**. Le dernier mot reste à l’arbitre du match."}$exo$::jsonb),
  ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9'::uuid, 3, 'redaction', $exo${"titre":"« Le hors-jeu, c’est pour embêter les attaquants »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Hugo affirme : *« Dès qu’un attaquant est devant tout le monde, c’est hors-jeu, et on ne peut jamais marquer sur une touche ou un corner sans que l’arbitre siffle. »*\n\n1. Montre en quoi **deux idées** de cette phrase sont fausses.\n2. Rédige ce qu’il faut savoir pour juger un hors-jeu : à quel moment on regarde, par rapport à qui, et dans quel cas le hors-jeu est sanctionné.\n3. Un but est refusé à la dernière minute. Un spectateur dit « l’arbitre est nul ». Écris deux ou trois phrases pour expliquer ce qui peut justifier la décision et ce qui peut aider à la vérifier.","bareme":[{"critere":"Deux erreurs corrigées : la position seule n’est pas sanctionnée ; pas de hors-jeu sur touche ni corner","points":6},{"critere":"Jugement : au moment de la passe, par rapport au ballon et à l’avant-dernier défenseur (gardien compris)","points":6},{"critere":"Sanction seulement si le joueur participe au jeu (touche le ballon, gêne, profite)","points":4},{"critere":"Explication de la décision et rôle de la VAR, dernier mot à l’arbitre","points":4}],"dureeMin":15,"corrige":"1. Première erreur : **être devant tout le monde n’est pas une faute**. Être en **position de hors-jeu** ne suffit pas : le joueur n’est sanctionné que s’il **participe au jeu**. Seconde erreur : sur une **touche**, un **corner** ou un **coup de pied de but**, il n’y a **jamais de hors-jeu** ; l’attaquant peut donc attendre devant la défense sans risque.\n\n2. On regarde **au moment où le coéquipier joue le ballon**. L’attaquant est en position de hors-jeu s’il est **plus près de la ligne de but adverse que le ballon et que l’avant-dernier défenseur** ; le **gardien compte comme défenseur**. Il n’y a pas de hors-jeu dans **sa moitié de terrain**. Le hors-jeu est **sanctionné** si le joueur **touche le ballon, gêne un adversaire ou profite de la situation**.\n\n3. Le but a pu être refusé parce que l’attaquant était en position de hors-jeu **au moment de la passe** et qu’il a ensuite touché le ballon. Pour vérifier, la **VAR** (assistance vidéo, utilisée en Coupe du monde depuis **2018**) aide l’arbitre à revoir l’image, mais **le dernier mot reste à l’arbitre** du match."}$exo$::jsonb),
  ('db2a6a93-e520-568c-8e31-b44eed648b59'::uuid, 1, 'redaction', $exo${"titre":"Les règles du basket","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. À quelle hauteur est le panier, et combien de joueurs une équipe aligne-t-elle sur le terrain ?\n2. Combien vaut un lancer franc ? un tir normal ? un tir derrière la ligne à trois points ?\n3. Que veut dire « **marcher** » au basket ?","bareme":[{"critere":"Panier à 3,05 m ; 5 joueurs par équipe","points":5},{"critere":"Lancer franc 1 point, tir normal 2 points, tir à 3 points","points":7},{"critere":"Marcher : faire plus de deux appuis avec le ballon sans dribbler (le ballon passe à l’adversaire)","points":8}],"dureeMin":7,"corrige":"1. Le panier est à **3,05 mètres** du sol et chaque équipe aligne **5 joueurs** sur le terrain.\n\n2. Un **lancer franc** vaut **1 point**, un tir normal **2 points**, et un tir **derrière la ligne à trois points** vaut **3 points**.\n\n3. **Marcher**, c’est avancer avec le ballon dans les mains en faisant **plus de deux appuis sans dribbler**. C’est une violation : le ballon passe à l’adversaire."}$exo$::jsonb),
  ('db2a6a93-e520-568c-8e31-b44eed648b59'::uuid, 2, 'redaction', $exo${"titre":"La fin de match de Malik","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Dernière minute. Malik, meneur de jeu, récupère le ballon dans son camp. Son équipe a deux points de retard.\n\n*Il garde le ballon 9 secondes avant de franchir la ligne médiane. Il arrive dans la raquette, attrape le ballon et fait trois pas sans dribbler. Son équipe n’a toujours pas tiré après 25 secondes.*\n\n1. Relève **trois erreurs** de l’équipe de Malik et dis, pour chacune, la règle qui s’applique.\n2. Malik recule derrière la ligne à 3 points et réussit son tir. Combien l’équipe marque-t-elle ? Passe-t-elle devant ?\n3. Un match de NBA dure plus longtemps qu’un match FIBA. Donne les deux durées.","bareme":[{"critere":"Trois erreurs relevées : 8 s pour franchir la ligne médiane ; marcher (plus de deux appuis) ; 24 s pour tirer","points":9},{"critere":"Tir à 3 points : 3 points, donc l’équipe passe devant d’un point","points":5},{"critere":"FIBA : 4 quarts-temps de 10 min ; NBA : 4 quarts-temps de 12 min","points":6}],"dureeMin":11,"corrige":"1. Première erreur : les **9 secondes** pour franchir la ligne médiane, alors qu’on n’a que **8 secondes**. Deuxième erreur : **trois pas sans dribbler**, c’est **marcher** (deux appuis au maximum), le ballon passe à l’adversaire. Troisième erreur : **25 secondes sans tirer**, alors qu’il faut tirer dans les **24 secondes**.\n\n2. Un tir derrière la ligne à trois points rapporte **3 points** : avec deux points de retard, l’équipe passe **devant d’un point**.\n\n3. En règles **FIBA**, un match dure **4 quarts-temps de 10 minutes** ; en **NBA**, **4 quarts-temps de 12 minutes**."}$exo$::jsonb),
  ('db2a6a93-e520-568c-8e31-b44eed648b59'::uuid, 3, 'redaction', $exo${"titre":"« Au basket, on peut courir avec le ballon »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Léa dit à sa classe : *« Au basket, on a le droit de courir avec le ballon comme au rugby, et il n’y a pas de limite de temps pour attaquer. Une faute, ça ne compte que si on se blesse. »*\n\n1. Corrige les **trois idées fausses** de Léa.\n2. Rédige un paragraphe qui explique à un camarade comment on avance avec le ballon au basket et ce qui est interdit.\n3. Compare la ligne à trois points en FIBA et en NBA : donne les deux distances et dis laquelle est la plus loin du panier.","bareme":[{"critere":"Trois idées corrigées : on avance en dribblant ; 24 s pour tirer (8 s, 3 s) ; toucher ou pousser est une faute personnelle","points":8},{"critere":"Avancer : dribbler ; deux appuis quand on tient le ballon ; marcher et reprise de dribble interdits","points":7},{"critere":"Ligne à 3 points : 6,75 m en FIBA, 7,24 m en NBA, plus loin en NBA","points":5}],"dureeMin":15,"corrige":"1. Première erreur : on ne court pas avec le ballon sans **dribbler**. Seconde erreur : il y a des **chronomètres** : **24 secondes** pour tirer, **8 secondes** pour franchir la ligne médiane, **3 secondes** maximum dans la raquette. Troisième erreur : toucher, pousser ou gêner un adversaire est une **faute personnelle**, même sans blessure. Au bout de **5 fautes** (6 en NBA), le joueur est **exclu**.\n\n2. Pour avancer, on **dribble**, c’est-à-dire qu’on fait rebondir le ballon. Quand on le tient dans les mains, on n’a droit qu’à **deux appuis**. Aller plus loin, c’est **marcher**. Si on arrête de dribbler, on ne peut pas **reprendre son dribble** : il faut passer ou tirer.\n\n3. La ligne à trois points est à **6,75 m** du panier en **FIBA** et à **7,24 m** en **NBA** : la NBA la place **plus loin**."}$exo$::jsonb),
  ('c0526fa0-9a21-518d-8170-2ce9788ecbf1'::uuid, 1, 'redaction', $exo${"titre":"Handball et volley : les bases","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Combien de joueurs une équipe de handball aligne-t-elle (gardien compris) et combien de temps dure un match ?\n2. Que veut dire la règle des **3 pas** et celle des **3 secondes** au handball ?\n3. Combien de touches une équipe de volley a-t-elle au maximum pour renvoyer le ballon, et à combien de points se gagne un set ?","bareme":[{"critere":"Handball : 7 joueurs (6 + gardien), 2 mi-temps de 30 minutes","points":5},{"critere":"3 pas avec le ballon en main au maximum ; ne pas garder le ballon plus de 3 secondes sans dribbler ni passer","points":8},{"critere":"Volley : 3 touches maximum ; set à 25 points avec 2 points d’écart","points":7}],"dureeMin":7,"corrige":"1. Une équipe de handball compte **7 joueurs** (6 joueurs de champ et un gardien). Un match dure **2 mi-temps de 30 minutes**.\n\n2. On ne fait pas plus de **trois pas** avec le ballon en main, et on ne le garde pas plus de **trois secondes** sans dribbler ni passer.\n\n3. Une équipe de volley a **3 touches maximum**. Un set se gagne à **25 points avec 2 points d’écart**."}$exo$::jsonb),
  ('c0526fa0-9a21-518d-8170-2ce9788ecbf1'::uuid, 2, 'redaction', $exo${"titre":"Deux matchs en EPS","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"En EPS, la classe de Camille joue au handball puis au volley.\n\n*Au handball, un joueur pose le pied dans la zone des 6 mètres pour tirer. Un autre fait cinq pas avec le ballon. Une équipe n’attaque plus et garde le ballon sans tenter de tirer.*\n*Au volley, une équipe touche quatre fois le ballon avant de le renvoyer. Le libéro saute et smashe au-dessus du filet.*\n\n1. Pour chaque situation de **handball**, explique ce que dit la règle.\n2. Pour chaque situation de **volley**, explique ce que dit la règle.\n3. Camille dit : « le libéro, c’est le meilleur attaquant ». Qu’en penses-tu ?","bareme":[{"critere":"Handball : zone des 6 m réservée au gardien ; 3 pas maximum ; jeu passif (il faut tirer vite)","points":7},{"critere":"Volley : 3 touches maximum ; le libéro ne peut pas attaquer au-dessus du filet","points":7},{"critere":"Le libéro est un joueur de défense, maillot de couleur différente, qui ne peut ni attaquer ni servir","points":6}],"dureeMin":11,"corrige":"1. **Zone des 6 m** : elle est **réservée au gardien**, les autres n’ont pas le droit d’y poser le pied (ils peuvent tirer en sautant au-dessus). **Cinq pas** : c’est trop, on ne fait pas plus de **trois pas** avec le ballon. **Pas d’attaque** : c’est le **jeu passif**, l’arbitre lève le bras et l’équipe doit tirer vite.\n\n2. **Quatre touches** : c’est interdit, une équipe a **3 touches maximum**. **Libéro qui smashe** : le libéro **ne peut pas attaquer** au-dessus du filet.\n\n3. Camille se trompe. Le **libéro** est un **joueur spécialisé dans la défense** : il porte un **maillot de couleur différente** et il **réceptionne et défend**, mais il ne peut **ni attaquer ni servir**."}$exo$::jsonb),
  ('c0526fa0-9a21-518d-8170-2ce9788ecbf1'::uuid, 3, 'redaction', $exo${"titre":"Handball ou volley : lequel choisir ?","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Pour la fête du collège, Noé veut organiser un tournoi. *« Au handball, on peut garder le ballon aussi longtemps qu’on veut, et un match s’arrête à 25 points. Au volley, il y a 6 joueurs par équipe, mais il suffit d’être le premier à 25 points pour gagner un set. »*\n\n1. Relève **les erreurs** dans la phrase de Noé et corrige-les.\n2. Compare les deux sports : pour chacun, donne le nombre de joueurs, la durée ou le score qui décide, et **une règle** qui oblige à jouer vite ou à collaborer.\n3. Le handball français a un très beau palmarès. Cite deux faits (équipe, année, titre) que tu connais.","bareme":[{"critere":"Erreurs corrigées : 3 secondes et 3 pas au handball ; 2 points d’écart au volley ; hand = 2 × 30 min, pas 25 points","points":7},{"critere":"Comparaison : hand 7 joueurs, 2 × 30 min, 3 pas ou 3 s ; volley 6 joueurs, set à 25 points, 3 touches, rotation","points":8},{"critere":"Palmarès : Experts (or 2008, 2012, 2020) et Bleues (or 2020)","points":5}],"dureeMin":15,"corrige":"1. Au handball, on ne garde pas le ballon : **3 pas** et **3 secondes** au maximum, et le **jeu passif** oblige à attaquer. Un match se joue en **2 mi-temps de 30 minutes** et ne s’arrête pas à 25 points. Au volley, un set se gagne à 25 points **avec 2 points d’écart** (et le **5e set** à 15 points).\n\n2. **Handball** : **7 joueurs**, **2 × 30 minutes**, **3 pas et 3 secondes**, zone des **6 m** réservée au gardien, exclusion de 2 minutes. **Volley** : **6 joueurs**, **sets à 25 points** (2 d’écart), **3 touches maximum**, **rotation** au service, **libéro** pour défendre ; le filet est à **2,43 m** (hommes) et **2,24 m** (femmes).\n\n3. Les **Experts** (équipe masculine) sont champions olympiques en **2008**, **2012** et **2020** ; les **Bleues** ont aussi conquis l’**or olympique en 2020**."}$exo$::jsonb),
  ('3d954a52-be6c-54b2-b2e3-c9cafc7b8ab2'::uuid, 1, 'redaction', $exo${"titre":"Les règles du rugby","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Combien de joueurs y a-t-il dans une équipe de rugby à XV et combien dure un match ?\n2. Qu’est-ce qu’un **en-avant** et que se passe-t-il ensuite ?\n3. Combien de points valent un **essai** et une **transformation** ?","bareme":[{"critere":"15 joueurs, 2 mi-temps de 40 minutes","points":5},{"critere":"En-avant : passer ou lâcher le ballon vers l’avant ; mêlée pour l’adversaire","points":8},{"critere":"Essai 5 points, transformation 2 points","points":7}],"dureeMin":7,"corrige":"1. Une équipe compte **15 joueurs** et un match dure **2 mi-temps de 40 minutes**.\n\n2. Un **en-avant**, c’est **passer ou lâcher le ballon vers l’avant**. L’arbitre siffle et l’équipe adverse obtient une **mêlée**.\n\n3. Un **essai** (ballon aplati dans l’en-but) vaut **5 points** et la **transformation** (tir après l’essai) vaut **2 points**."}$exo$::jsonb),
  ('3d954a52-be6c-54b2-b2e3-c9cafc7b8ab2'::uuid, 2, 'redaction', $exo${"titre":"Un match de rugby à commenter","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Tu commentes un match de rugby.\n\n*Un joueur passe le ballon vers l’avant à son coéquipier. Plus tard, un plaqueur attrape le porteur au niveau du cou. Enfin, un joueur aplatit le ballon dans l’en-but, puis son équipe tape la transformation.*\n\n1. Que fait l’arbitre pour **chaque** action ? Explique les règles.\n2. Combien de points l’équipe marque-t-elle sur la dernière action si la transformation est réussie ?\n3. La France a gagné à Paris 2024 en rugby à 7. Combien de joueurs par équipe et combien de temps dure un match à 7 ?","bareme":[{"critere":"Passe vers l’avant : en-avant, mêlée ; plaquage au cou : interdit, il faut plaquer sous la ligne des épaules","points":8},{"critere":"Essai (5) + transformation réussie (2) = 7 points","points":6},{"critere":"Rugby à 7 : 7 joueurs, matchs de 2 × 7 minutes","points":6}],"dureeMin":11,"corrige":"1. **Passe vers l’avant** : c’est un **en-avant**, l’arbitre siffle et l’adversaire a une **mêlée**. **Plaquage au cou** : il est **interdit et puni**, on doit plaquer **sous la ligne des épaules**. **Ballon aplati dans l’en-but** : c’est un **essai**, suivi d’une **transformation**.\n\n2. Un essai vaut **5 points** et la transformation réussie **2 points** : l’équipe marque **7 points**.\n\n3. Le rugby à 7 se joue à **7 par équipe**, en matchs de **2 × 7 minutes**. La France a remporté l’or olympique à **Paris 2024**."}$exo$::jsonb),
  ('3d954a52-be6c-54b2-b2e3-c9cafc7b8ab2'::uuid, 3, 'redaction', $exo${"titre":"« Le rugby, c’est un sport sans règles »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Sam dit : *« Au rugby, on fonce tête baissée, on peut passer le ballon dans tous les sens et on plaque où on veut. Ça ne sert à rien de respecter l’arbitre. »*\n\n1. Corrige **trois idées fausses** de Sam avec les règles du rugby.\n2. Explique en quelques phrases comment une équipe peut marquer des points. Donne les quatre façons et leur valeur.\n3. Pourquoi dit-on « Monsieur » à l’arbitre ? Que représente cette habitude pour le rugby ?","bareme":[{"critere":"Trois idées corrigées : ballon en arrière ou sur le côté ; plaquage sous les épaules ; respect de l’arbitre","points":7},{"critere":"Essai 5, transformation 2, pénalité 3, drop 3","points":8},{"critere":"Respect de l’arbitre : « Monsieur », seul le capitaine lui parle, esprit du jeu","points":5}],"dureeMin":15,"corrige":"1. On ne peut passer le ballon qu’**en arrière ou sur le côté** : vers l’avant, c’est un **en-avant** et une mêlée pour l’adversaire. On plaque **sous la ligne des épaules**, jamais au cou ni à la tête. Et on **respecte l’arbitre**, on ne le conteste pas.\n\n2. L’**essai** (ballon aplati dans l’en-but) vaut **5 points**, la **transformation** (tir après l’essai) **2 points**, la **pénalité** (tir entre les poteaux) **3 points** et le **drop** (coup de pied tombé en plein jeu) **3 points**.\n\n3. On s’adresse à l’arbitre par « **Monsieur** » et seul le **capitaine** lui parle : c’est une règle de politesse qui fait partie de l’**esprit du jeu**, où l’on respecte l’arbitre même dans un sport de contact."}$exo$::jsonb),
  ('cefd17c1-1bb1-52a3-8625-adcf7a181519'::uuid, 1, 'redaction', $exo${"titre":"Lire un score de tennis","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Comment s’appellent les points dans un jeu de tennis, et que se passe-t-il à « 40 partout » ?\n2. À combien de jeux gagne-t-on un set, et que se passe-t-il à 6-6 ?\n3. Combien de balles de service a-t-on, et que se passe-t-il si les deux sont fautes ?","bareme":[{"critere":"15, 30, 40 ; à 40 partout, égalité puis avantage (2 points d’écart)","points":7},{"critere":"Set à 6 jeux avec 2 d’écart ; à 6-6, tie-break","points":7},{"critere":"Deux balles de service ; deux fautes = double faute, point perdu","points":6}],"dureeMin":7,"corrige":"1. Les points s’appellent **15, 30, 40**. À **40 partout**, c’est l’**égalité** : il faut **deux points d’écart**, avec un **avantage** pour celui qui gagne le point suivant.\n\n2. Un **set** se gagne à **6 jeux avec 2 jeux d’écart**. À **6-6**, un **tie-break** décide du set.\n\n3. On a **deux balles de service**. Si les deux sont fautes, c’est une **double faute** et le **point est perdu**."}$exo$::jsonb),
  ('cefd17c1-1bb1-52a3-8625-adcf7a181519'::uuid, 2, 'redaction', $exo${"titre":"Lire un score affiché","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Sur l’écran du stade, tu lis le score d’un match gagné par le joueur A : *« 6-4, 3-6, 7-6 »*. Plus tard, tu regardes un match de badminton.\n\n1. Qui a gagné chaque set et le match ? Explique comment tu le sais.\n2. Dans le troisième set, comment est-on arrivé à 7-6 ? Décris ce qui se passe à 6-6.\n3. Au badminton, à combien de points se gagne un set, combien de sets faut-il gagner, et comment sert-on ?","bareme":[{"critere":"A gagne le 1er set (6-4), perd le 2e (3-6), gagne le 3e : 2 sets à 1, le match est à A","points":7},{"critere":"À 6-6 : tie-break, premier à 7 points avec 2 points d’écart","points":6},{"critere":"Badminton : set à 21 points (2 d’écart, plafond 30), 2 sets gagnants, service par en dessous","points":7}],"dureeMin":11,"corrige":"1. Le joueur A gagne le **premier set 6-4**, perd le **deuxième 3-6**, puis gagne le **troisième au tie-break (7-6)**. Il a donc gagné **2 sets contre 1** : le **match est à lui**.\n\n2. À **6-6** dans un set, on joue un **tie-break** : le premier à **7 points avec 2 points d’écart** remporte le set.\n\n3. Un set de badminton se joue en **21 points** avec **2 points d’écart**, plafonné à **30**. Il faut gagner **2 sets**. Le service se fait **par en dessous**."}$exo$::jsonb),
  ('cefd17c1-1bb1-52a3-8625-adcf7a181519'::uuid, 3, 'redaction', $exo${"titre":"« Au tennis, on gagne dès qu’on a plus de points »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Zoé affirme : *« Au tennis, le premier à 40 points gagne le jeu. Un set, c’est le premier à 6 jeux, même avec un seul jeu d’avance. Et le smash le plus rapide, c’est au tennis, pas au badminton. »*\n\n1. Corrige **chacune** des trois affirmations de Zoé.\n2. Explique pourquoi le tennis est un sport « à deux d’écart » : donne trois exemples (point, jeu, tie-break).\n3. Présente Roland-Garros en deux ou trois phrases : surface, ville, et le recordman de victoires.","bareme":[{"critere":"Trois corrections : 40 puis le point suivant (égalité, avantage) ; 6 jeux avec 2 d’écart ; smash de badminton plus rapide","points":9},{"critere":"Trois exemples d’écart de deux : points à l’égalité, jeux dans un set, points au tie-break","points":6},{"critere":"Roland-Garros : terre battue, Paris, Rafael Nadal 14 titres","points":5}],"dureeMin":15,"corrige":"1. Il ne suffit pas d’arriver à 40 : à **40 partout** c’est l’**égalité** et il faut **deux points d’écart** (avantage). Un **set** se gagne à **6 jeux avec 2 jeux d’écart** (6-4), et à 6-6 on joue un **tie-break**. Enfin, le **smash de badminton** est le plus rapide de tous les sports de raquette : plus de **400 km/h** ont été mesurés en match.\n\n2. Au tennis, on gagne toujours avec **deux unités d’écart** : **deux points** à l’égalité, **deux jeux** dans un set, **deux points** au tie-break (qui se joue en 7 points).\n\n3. **Roland-Garros** se joue à **Paris**, sur **terre battue** ; son stade date de **1928**. Le recordman est l’Espagnol **Rafael Nadal**, vainqueur **14 fois**."}$exo$::jsonb),
  ('caf2e6dc-508d-55a9-9839-889dc574b8da'::uuid, 1, 'redaction', $exo${"titre":"Pourquoi on transpire","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quelle est la température normale du corps ? Pourquoi un muscle qui travaille fait-il monter la chaleur ?\n2. Qu’est-ce qui refroidit vraiment le corps : la sueur qui coule ou la sueur qui s’évapore ?\n3. Pourquoi faut-il boire **avant d’avoir soif** ?","bareme":[{"critere":"Le corps tient 37 °C ; trois quarts de l’énergie du muscle partent en chaleur","points":6},{"critere":"Seule la sueur qui s’évapore refroidit la peau","points":7},{"critere":"Quand la soif apparaît, le manque d’eau a déjà commencé","points":7}],"dureeMin":7,"corrige":"1. Le corps doit rester autour de **37 °C**. Un muscle qui travaille est un petit moteur peu efficace : environ **un quart** de l’énergie sert à bouger et **les trois quarts partent en chaleur**.\n\n2. C’est la sueur qui **s’évapore** qui refroidit : en passant de liquide à gaz, l’eau prend de la chaleur à la peau. La sueur qui coule ne refroidit pas.\n\n3. Quand la soif apparaît, **le manque d’eau a déjà commencé**. On boit donc **avant d’avoir soif**, par petites gorgées, avant, pendant et après l’effort."}$exo$::jsonb),
  ('caf2e6dc-508d-55a9-9839-889dc574b8da'::uuid, 2, 'redaction', $exo${"titre":"Le match sous la chaleur","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Un après-midi d’été, Yanis joue au foot pendant une heure avec un k-way imperméable et sans gourde. Il devient très rouge, il a mal à la tête, il a des vertiges et il est confus.\n\n1. Explique pourquoi Yanis est tout rouge et pourquoi son imperméable est une mauvaise idée pour son refroidissement.\n2. De quoi souffre-t-il probablement ? Cite trois signes d’alerte du texte.\n3. Ses amis doivent l’aider. Donne quatre gestes à faire, puis dis à quel moment il faut appeler les secours et quel numéro composer.","bareme":[{"critere":"Rougeur : les vaisseaux de la peau se dilatent pour évacuer la chaleur ; l’imperméable bloque l’évaporation de la sueur","points":7},{"critere":"Coup de chaleur ; trois signes (peau rouge et chaude, mal de tête, vertiges, nausées, confusion)","points":5},{"critere":"Gestes : arrêter l’effort, ombre, allonger, boire par petites gorgées, refroidir à l’eau fraîche ; secours (15 ou 112) sans amélioration","points":8}],"dureeMin":11,"corrige":"1. Yanis est rouge parce que ses **vaisseaux sanguins sous la peau se dilatent** pour laisser sortir la chaleur. Son **imperméable bloque l’évaporation** de la sueur : or c’est l’évaporation qui refroidit, donc il surchauffe.\n\n2. Il fait probablement un **coup de chaleur**. Signes d’alerte : **peau très rouge et chaude, mal de tête, vertiges, nausées, confusion**.\n\n3. Ses amis doivent **arrêter l’effort**, le mettre **à l’ombre**, l’**allonger**, le faire **boire par petites gorgées** et le **refroidir avec de l’eau fraîche**. S’il n’y a **pas d’amélioration**, il faut **appeler les secours** : le **15** ou le **112**."}$exo$::jsonb),
  ('caf2e6dc-508d-55a9-9839-889dc574b8da'::uuid, 3, 'redaction', $exo${"titre":"« Transpirer, c’est perdre du gras »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Lina dit : *« Quand je transpire beaucoup, c’est que mon corps fond. Le mieux, c’est de s’entraîner avec trois pulls pour transpirer encore plus, et de ne pas boire pour ne pas ralentir. »*\n\n1. Corrige l’idée de Lina sur **le rôle de la sueur**.\n2. Explique en un paragraphe pourquoi s’entraîner avec trois pulls et sans boire est dangereux.\n3. Rédige les conseils que tu donnerais à Lina : comment s’habiller, quoi emporter, quand boire. Appuie-toi sur la bouteille d’eau et les couches de vêtements.","bareme":[{"critere":"La sueur est le radiateur du corps : elle refroidit en s’évaporant, elle ne mesure pas une perte de gras","points":6},{"critere":"Danger : la chaleur monte, l’évaporation est bloquée, 1 à 2 litres perdus par heure, coup de chaleur","points":8},{"critere":"Conseils : couches respirantes, casquette, gourde pleine, boire avant d’avoir soif par petites gorgées","points":6}],"dureeMin":15,"corrige":"1. La sueur n’est pas du gras qui fond : c’est de l’**eau avec un peu de sel**, que les **glandes sudoripares** (2 à 4 millions) sécrètent pour **refroidir** le corps **en s’évaporant**. Le corps doit rester autour de **37 °C**.\n\n2. Avec trois pulls, la sueur **ne peut plus s’évaporer** : le corps ne se refroidit pas et peut faire un **coup de chaleur**. Sans boire, la **déshydratation** arrive vite : on peut perdre **1 à 2 litres par heure** à l’effort, avec fatigue, maux de tête et crampes.\n\n3. Je lui dirais de s’habiller **en couches** : une couche **respirante** contre la peau, une plus chaude qu’elle enlève quand elle chauffe, une **casquette** s’il fait très chaud, pas de coton trempé. Elle doit emporter une **gourde pleine** et **boire avant d’avoir soif**, par petites gorgées, avant, pendant et après l’effort."}$exo$::jsonb),
  ('fa6391f9-219d-512b-9b29-bda6efed26c9'::uuid, 1, 'redaction', $exo${"titre":"Le cœur et le souffle","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quel est le nombre de battements du cœur au repos, par minute ? Comment le compte-t-on au poignet ?\n2. Pourquoi respire-t-on plus vite à l’effort ?\n3. Que faire quand on a un **point de côté** ?","bareme":[{"critere":"60 à 80 battements par minute (un peu plus chez l’enfant) ; deux doigts au poignet, 15 secondes × 4","points":6},{"critere":"On respire plus vite pour apporter l’oxygène aux muscles et évacuer le gaz carbonique (CO2)","points":7},{"critere":"Ralentir, respirer profondément en soufflant longtemps, presser l’endroit douloureux","points":7}],"dureeMin":7,"corrige":"1. Au repos, le cœur bat **60 à 80 fois par minute** (un peu plus chez un enfant). On pose **deux doigts sur le poignet**, du côté du pouce, on compte les battements pendant **15 secondes** et on **multiplie par 4**.\n\n2. À l’effort, les muscles réclament de l’**oxygène**. On respire plus vite et plus profond pour **apporter l’oxygène** et **évacuer le gaz carbonique (CO2)**.\n\n3. Pour faire passer un point de côté, on **ralentit** (ou on marche), on **respire profondément** en soufflant longtemps et on **presse avec la main** à l’endroit douloureux."}$exo$::jsonb),
  ('fa6391f9-219d-512b-9b29-bda6efed26c9'::uuid, 2, 'redaction', $exo${"titre":"L’expérience du pouls","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Karim mesure son pouls : *« 18 battements en 15 secondes au repos. Après une course de deux minutes : 40 battements en 15 secondes. »* Pendant la course, il a senti une douleur sous les côtes, à droite.\n\n1. Calcule le pouls de Karim au repos, puis après la course, en battements par minute. Que constates-tu ?\n2. Pourquoi le cœur accélère-t-il à l’effort ? Combien de sang envoie-t-il par minute au repos et à l’effort ?\n3. Nomme la douleur de Karim. Que faut-il faire, et que ne faut-il pas faire juste avant de courir ?","bareme":[{"critere":"Repos : 18 × 4 = 72 par minute ; effort : 40 × 4 = 160 par minute ; le cœur a accéléré","points":7},{"critere":"Le cœur envoie plus de sang et d’oxygène aux muscles : environ 5 litres par minute au repos, 20 à 25 à l’effort","points":7},{"critere":"Point de côté ; ralentir et respirer profondément ; ne pas manger juste avant de courir","points":6}],"dureeMin":11,"corrige":"1. Au repos : 18 × 4 = **72 battements par minute**. Après la course : 40 × 4 = **160 battements par minute**. Le cœur de Karim a **beaucoup accéléré** pour répondre à l’effort.\n\n2. Les muscles réclament plus d’**oxygène** : le cœur envoie plus de sang. Il pompe environ **5 litres par minute au repos** et **20 à 25 litres à l’effort**.\n\n3. C’est un **point de côté**, dont les causes ne sont pas totalement connues. Karim doit **ralentir**, **respirer profondément** et souffler longtemps. Pour l’éviter, on **ne mange pas juste avant** de courir et on s’échauffe doucement."}$exo$::jsonb),
  ('fa6391f9-219d-512b-9b29-bda6efed26c9'::uuid, 3, 'redaction', $exo${"titre":"« Être essoufflé, c’est être en mauvaise santé »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Paul dit : *« Quand je suis essoufflé après une course, c’est que mon cœur est malade. Un champion n’est jamais essoufflé, et son cœur bat toujours très vite. »*\n\n1. Explique pourquoi l’essoufflement à l’effort est **normal**. Que fait le corps à ce moment-là ?\n2. Rédige ce que devient le cœur d’un sportif qui s’entraîne en endurance : que se passe-t-il pour son pouls au repos ? Donne un chiffre.\n3. Dans quels cas Paul doit-il signaler le problème à un adulte ?","bareme":[{"critere":"L’essoufflement est un signe d’adaptation : cœur et respiration accélèrent ; il diminue avec l’entraînement","points":7},{"critere":"Cœur d’athlète : muscle renforcé, pompe plus de sang par battement, bat plus lentement au repos (autour de 40 chez certains)","points":8},{"critere":"Douleur dans la poitrine, malaise ou essoufflement anormal : prévenir un adulte","points":5}],"dureeMin":15,"corrige":"1. Être essoufflé à l’effort est **normal** : c’est le signe que le corps **s’adapte**. Le cœur accélère pour envoyer du sang et de l’oxygène aux muscles, on respire plus vite et plus profond pour apporter l’**oxygène** et évacuer le **gaz carbonique (CO2)**. Avec l’**entraînement**, on s’essouffle moins vite.\n\n2. Le cœur est un **muscle** : il se **renforce** avec l’endurance. Il pompe **plus de sang à chaque battement**, donc **au repos il bat plus lentement**. Chez certains champions, on a mesuré environ **40 battements par minute** (c’est le « cœur d’athlète »).\n\n3. Il faut le dire tout de suite à un adulte en cas de **douleur dans la poitrine**, de **malaise** ou d’**essoufflement anormal**."}$exo$::jsonb),
  ('ce11cf8e-9358-5d06-b30c-56df1ddda976'::uuid, 1, 'redaction', $exo${"titre":"Crampe, courbature, ampoule","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Qu’est-ce qu’une **crampe** ? Que faire ?\n2. Quand apparaît une **courbature** et d’où vient-elle ?\n3. Que signifient les quatre lettres du **GREC** ?","bareme":[{"critere":"Crampe : contraction brutale et involontaire du muscle ; étirer doucement, masser, boire","points":7},{"critere":"Courbature : 24 à 48 h après un effort inhabituel, micro-lésions des fibres","points":6},{"critere":"GREC : Glace, Repos, Élévation, Compression","points":7}],"dureeMin":7,"corrige":"1. La **crampe** est une **contraction brutale, douloureuse et involontaire** du muscle (fatigue, parfois déshydratation). On **étire doucement** le muscle, on le **masse** et on **boit**.\n\n2. La **courbature** apparaît **24 à 48 heures** après un effort inhabituel et vient de **micro-lésions** dans les fibres du muscle.\n\n3. **G** comme **Glace**, **R** comme **Repos**, **E** comme **Élévation** de la jambe, **C** comme **Compression** avec une bande."}$exo$::jsonb),
  ('ce11cf8e-9358-5d06-b30c-56df1ddda976'::uuid, 2, 'redaction', $exo${"titre":"Les bobos de Maëlle","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Maëlle s’est entraînée dur. Le soir, son mollet se contracte d’un coup. Le lendemain, elle a des courbatures et elle trouve ça génial : *« Ça prouve que je progresse ! »* Elle a aussi une ampoule au talon, grosse mais intacte. Plus tard, sa cheville tourne en jouant et elle ne peut plus poser le pied.\n\n1. Que s’est-il passé pour son mollet ? Que fait-elle ?\n2. Maëlle a-t-elle raison sur les courbatures ? Que fait-elle de son ampoule ?\n3. Pour la cheville, que doit-elle faire et que doit-elle faire en plus puisqu’elle ne peut pas poser le pied ?","bareme":[{"critere":"Crampe : étirer doucement le muscle, masser, boire","points":5},{"critere":"Courbature : micro-lésions, pas une preuve de progrès ; ampoule : ne pas la percer, pansement adapté","points":8},{"critere":"Entorse : GREC puis consulter, car elle ne peut pas poser le pied","points":7}],"dureeMin":11,"corrige":"1. C’est une **crampe**, une contraction brutale et involontaire du mollet. Maëlle doit **étirer doucement** le muscle, le **masser** et **boire**.\n\n2. Non : les courbatures viennent de **micro-lésions** des fibres, elles **ne prouvent pas un progrès**. Pour l’ampoule, il vaut mieux **ne pas la percer** (la peau protège des microbes) et la protéger avec un **pansement adapté** ; si elle est grosse et gênante, on la perce avec une aiguille **désinfectée** en gardant la peau.\n\n3. C’est une **entorse** : elle applique le **GREC** (glace enveloppée, repos, élévation, compression). Comme elle ne peut pas poser le pied, elle doit **consulter un médecin**."}$exo$::jsonb),
  ('ce11cf8e-9358-5d06-b30c-56df1ddda976'::uuid, 3, 'redaction', $exo${"titre":"« Avoir mal, c’est normal : on continue »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Tom dit : *« Une cheville qui fait mal, ça se soigne en continuant à jouer. Une ampoule, il faut la percer tout de suite avec ce qui traîne. Et je n’emporte jamais rien à l’entraînement. »*\n\n1. Montre que le conseil de Tom pour la cheville est dangereux. Que fait-on à la place ?\n2. Réponds à ses idées sur l’ampoule : pourquoi vaut-il mieux ne pas la percer, et comment l’éviter ?\n3. Compose le kit idéal de l’élève sportif et donne trois cas où il faut voir un médecin.","bareme":[{"critere":"Continuer sur une articulation blessée transforme un bobo en blessure longue ; on arrête et on applique le GREC","points":6},{"critere":"Ampoule : la peau protège des microbes, on protège avec un pansement ; éviter par chaussures à la bonne taille et chaussettes sans plis","points":6},{"critere":"Kit : gourde, pansements adaptés, chaussettes de rechange, serviette ; médecin : ne peut pas poser le pied, articulation déformée, douleur la nuit","points":8}],"dureeMin":15,"corrige":"1. Continuer à jouer sur une articulation blessée **transforme un bobo en blessure longue**. En cas de douleur, **on arrête** et on applique le **GREC** : **glace**, **repos**, **élévation**, **compression**.\n\n2. Il vaut mieux **ne pas percer** l’ampoule : la peau protège la plaie des **microbes**. On la protège avec un **pansement adapté**. Pour l’éviter : **chaussures à la bonne taille**, **chaussettes sans couture** qui plissent.\n\n3. Le kit : une **gourde** pleine, des **pansements** adaptés (anti-ampoules), des **chaussettes** de rechange, une serviette ou un petit vêtement chaud. On voit un médecin si on **ne peut pas poser le pied** ou marcher, si l’articulation est **gonflée ou déformée**, ou si la douleur **réveille la nuit**."}$exo$::jsonb),
  ('d2a12631-87c5-5489-b6df-89d41fb5df00'::uuid, 1, 'redaction', $exo${"titre":"Les Jeux olympiques : repères","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Où et en quelle année ont eu lieu les premiers Jeux connus de l’Antiquité ? En l’honneur de qui ?\n2. Qui a fait renaître les Jeux, et où ont eu lieu les premiers Jeux modernes (année) ?\n3. Que représentent les cinq anneaux olympiques ?","bareme":[{"critere":"Olympie (Grèce), 776 avant J.-C., en l’honneur de Zeus","points":7},{"critere":"Pierre de Coubertin ; Athènes en 1896","points":7},{"critere":"Les cinq continents","points":6}],"dureeMin":7,"corrige":"1. Les premiers Jeux connus ont lieu à **Olympie**, en Grèce, en **776 avant J.-C.**, en l’honneur de **Zeus**, tous les **4 ans**.\n\n2. C’est le baron **Pierre de Coubertin** qui les fait renaître. Les premiers Jeux modernes se tiennent à **Athènes** en **1896**.\n\n3. Les **cinq anneaux** (créés en **1913**) représentent les **cinq continents**."}$exo$::jsonb),
  ('d2a12631-87c5-5489-b6df-89d41fb5df00'::uuid, 2, 'redaction', $exo${"titre":"Une frise des Jeux","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Tu prépares une frise avec ces dates : **776 av. J.-C. · 393 · 1896 · 1924 · 1948 · 1960 · 2024**.\n\n1. Associe à chaque date l’événement qui lui correspond (Jeux interdits, Chamonix, Stoke Mandeville, Rome, Athènes, Olympie, Paris).\n2. Pourquoi la trêve sacrée est-elle importante dans l’Antiquité ? Que reçoit le vainqueur de la course du stade ?\n3. Donne trois chiffres de Paris 2024 (dates, sports ou épreuves, athlètes) et un fait sur la cérémonie d’ouverture.","bareme":[{"critere":"Six ou sept dates bien associées (776 Olympie, 393 interdits, 1896 Athènes, 1924 Chamonix, 1948 Stoke Mandeville, 1960 Rome, 2024 Paris)","points":9},{"critere":"Trêve sacrée : les guerres entre cités s’arrêtent ; couronne d’olivier","points":5},{"critere":"Paris 2024 : 26 juillet–11 août, 32 sports, 329 épreuves, environ 10 500 athlètes ; cérémonie sur la Seine","points":6}],"dureeMin":11,"corrige":"1. **776 av. J.-C.** : premiers Jeux connus, à **Olympie**. **393** : les Jeux sont **interdits**. **1896** : premiers Jeux modernes, à **Athènes**. **1924** : premiers Jeux d’hiver, à **Chamonix**. **1948** : **Stoke Mandeville**, naissance du mouvement paralympique. **1960** : premiers Jeux paralympiques, à **Rome**. **2024** : Jeux de **Paris**.\n\n2. La **trêve sacrée** suspend les **guerres entre cités** pendant les Jeux. Le vainqueur de la **course du stade** (192 mètres) reçoit une **couronne d’olivier**.\n\n3. Paris 2024 : du **26 juillet au 11 août**, **32 sports**, **329 épreuves**, environ **10 500 athlètes**, avec la **parité** hommes-femmes. La cérémonie d’ouverture a eu lieu **sur la Seine**, une première."}$exo$::jsonb),
  ('d2a12631-87c5-5489-b6df-89d41fb5df00'::uuid, 3, 'redaction', $exo${"titre":"« Les Jeux, c’est toujours pareil depuis l’Antiquité »","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Rayan dit : *« Les Jeux olympiques n’ont pas changé depuis 2 800 ans : mêmes athlètes, mêmes épreuves, et seulement des hommes. Les Jeux paralympiques ont toujours existé. »*\n\n1. Montre par **trois exemples** que les Jeux ont beaucoup changé entre l’Antiquité et aujourd’hui.\n2. Retrace en quelques phrases comment sont nés les **Jeux paralympiques**, avec deux dates.\n3. Explique ce que les Jeux de Paris 2024 ont de nouveau, et cite un résultat de la France.","bareme":[{"critere":"Trois changements : renaissance en 1896 par Coubertin, Jeux d’hiver (1924), symboles (anneaux 1913, flamme 1928), femmes et parité","points":8},{"critere":"Paralympiques : Stoke Mandeville 1948 (fauteuil roulant), premiers Jeux officiels à Rome en 1960","points":6},{"critere":"Paris 2024 : cérémonie sur la Seine, parité ; France 5e nation, 64 médailles dont 16 d’or (ou Léon Marchand 4 titres)","points":6}],"dureeMin":15,"corrige":"1. Les Jeux ont changé : **interdits en 393**, ils renaissent en **1896** avec **Pierre de Coubertin** ; il y a maintenant des **Jeux d’hiver** (Chamonix, **1924**), des **symboles** (les **anneaux** en 1913, la **flamme** en 1928, le **relais** depuis 1936) et, en **1896**, il n’y avait que des hommes alors qu’à Paris 2024 il y a la **parité**.\n\n2. Tout commence à **Stoke Mandeville**, en Angleterre, en **1948**, avec des athlètes en **fauteuil roulant**. Les premiers Jeux paralympiques officiels ont lieu à **Rome** en **1960**.\n\n3. À Paris 2024, la **cérémonie d’ouverture** a lieu **sur la Seine** (une première) et il y a la **parité** entre hommes et femmes. La **France** finit **5e nation** avec **64 médailles** dont **16 d’or** ; **Léon Marchand** remporte **4 titres**."}$exo$::jsonb),
  ('97b57b36-d205-58bb-a3d0-1edad7be0731'::uuid, 1, 'redaction', $exo${"titre":"Champions français : qui est qui ?","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Dans quel sport Teddy Riner est-il champion et dans quel sport Léon Marchand ?\n2. Quel champion a marqué deux buts de la tête en finale de la Coupe du monde 1998, et contre quelle équipe ?\n3. Quelle athlète a gagné le 400 m aux Jeux de Barcelone en 1992 ?","bareme":[{"critere":"Riner : judo ; Marchand : natation","points":6},{"critere":"Zinédine Zidane, face au Brésil, 3-0 au Stade de France","points":8},{"critere":"Marie-José Pérec","points":6}],"dureeMin":7,"corrige":"1. **Teddy Riner** est champion de **judo** (plus de 100 kg) et **Léon Marchand** de **natation**.\n\n2. C’est **Zinédine Zidane** qui marque **deux buts de la tête** en finale de la Coupe du monde **1998**, contre le **Brésil** (la France gagne **3-0** au Stade de France).\n\n3. C’est **Marie-José Pérec**, qui gagne le 400 m à **Barcelone en 1992**."}$exo$::jsonb),
  ('97b57b36-d205-58bb-a3d0-1edad7be0731'::uuid, 2, 'redaction', $exo${"titre":"Associe champion et exploit","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Voici cinq exploits. Retrouve le champion de chacun parmi : Tony Parker, Martin Fourcade, Laure Manaudou, Jean-Claude Killy, Kylian Mbappé.\n\n*A : 5 titres olympiques de biathlon, entre 2014 et 2018.*\n*B : trois titres olympiques de ski à Grenoble en 1968.*\n*C : 4 titres NBA avec San Antonio (2003, 2005, 2007 et 2014).*\n*D : or du 400 m nage libre à Athènes en 2004, à 17 ans.*\n*E : champion du monde en 2018 à 19 ans, 4 buts.*\n\n1. Associe chaque exploit à son champion et à son sport.\n2. Quel point commun les champions ont-ils, d’après le cours, avant de devenir célèbres ?\n3. Choisis un des cinq champions et écris-en deux phrases qui donnent envie de le découvrir.","bareme":[{"critere":"Cinq associations : A Fourcade (biathlon), B Killy (ski), C Parker (basket), D Manaudou (natation), E Mbappé (football)","points":10},{"critere":"Point commun : ils ont commencé jeunes dans un club avec un entraîneur et de la régularité","points":5},{"critere":"Deux phrases cohérentes avec un exploit exact du cours","points":5}],"dureeMin":11,"corrige":"1. **A** : **Martin Fourcade**, biathlon (courir vite, puis tirer juste). **B** : **Jean-Claude Killy**, ski alpin. **C** : **Tony Parker**, basket. **D** : **Laure Manaudou**, natation. **E** : **Kylian Mbappé**, football.\n\n2. Aucun n’est devenu champion en un jour : tous ont **commencé jeunes, dans un club** près de chez eux, avec un **entraîneur** et de la **régularité**.\n\n3. Exemple : « **Tony Parker** a gagné **4 titres NBA** avec San Antonio (2003, 2005, 2007 et 2014). Un Français sur le toit du basket mondial : ça donne envie de s’entraîner. »"}$exo$::jsonb),
  ('97b57b36-d205-58bb-a3d0-1edad7be0731'::uuid, 3, 'redaction', $exo${"titre":"Un champion, ça ne s’invente pas","consigne":"Rédige ta réponse en t’appuyant sur le vocabulaire du cours.","enonce":"Ilyès dit : *« Les champions sont des gens qui ont du talent dès la naissance. Pas besoin de travailler. Et la France n’a gagné de médailles qu’au football. »*\n\n1. Corrige l’idée sur le talent avec ce que dit le cours, et cite un exemple de champion.\n2. Réponds à « la France n’a gagné qu’au football » en citant **quatre** champions français dans quatre sports différents, avec un exploit exact pour chacun.\n3. Présente en deux ou trois phrases Teddy Riner ou Clarisse Agbegnenou : discipline, exploit, date.","bareme":[{"critere":"Un champion, c’est des années de travail, des défaites, de la régularité ; un exemple cité","points":6},{"critere":"Quatre sports différents, quatre champions avec un exploit exact","points":8},{"critere":"Portrait exact de Riner (judo, ors 2012, 2016, 2024, 11 titres mondiaux) ou d’Agbegnenou (−63 kg, or à Tokyo 2021)","points":6}],"dureeMin":15,"corrige":"1. Un champion, ce n’est pas seulement un talent : c’est **des années de travail**, des **défaites** et **un jour où tout se joue**. Tous ont commencé **jeunes, dans un club**, avec un **entraîneur** et de la **régularité**. Exemple : **Marie-José Pérec**, or sur 400 m à Barcelone en 1992.\n\n2. La France brille dans bien d’autres sports : **Léon Marchand** (natation, 4 ors à Paris 2024), **Teddy Riner** (judo, ors 2012, 2016, 2024), **Tony Parker** (basket, 4 titres NBA) et **Martin Fourcade** (biathlon, 5 ors olympiques).\n\n3. **Teddy Riner** est champion olympique individuel de **judo** (plus de 100 kg) en **2012, 2016 et 2024**, avec deux ors par équipes et **11 titres mondiaux**. **Clarisse Agbegnenou**, elle, est championne olympique en **−63 kg** à **Tokyo, en 2021**."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('e5bbb0ea-b126-5c6c-9af6-b681ac7487a9', 'db2a6a93-e520-568c-8e31-b44eed648b59', 'c0526fa0-9a21-518d-8170-2ce9788ecbf1', '3d954a52-be6c-54b2-b2e3-c9cafc7b8ab2', 'cefd17c1-1bb1-52a3-8625-adcf7a181519', 'caf2e6dc-508d-55a9-9839-889dc574b8da', 'fa6391f9-219d-512b-9b29-bda6efed26c9', 'ce11cf8e-9358-5d06-b30c-56df1ddda976', 'd2a12631-87c5-5489-b6df-89d41fb5df00', '97b57b36-d205-58bb-a3d0-1edad7be0731');
  RAISE NOTICE '569 : % sujets au catalogue (attendu : 30)', n;
  IF n < 30 THEN
    RAISE WARNING '569 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
